T=$(mktemp -d) || exit 1; chmod 755 "$T"; mkdir -p "$T/db/sync"; ln -s /var/lib/pacman/local "$T/db/local"; cp -p /var/lib/pacman/sync/*.db "$T/db/sync/" 2>/dev/null; if pacman -Sy --dbpath "$T/db" --logfile /dev/null >/dev/null 2>&1; then pacman -Qu --dbpath "$T/db" 2>/dev/null | grep -c .; r=0; else r=1; fi; rm -f "$T/db/local" "$T/db/db.lck" "$T"/db/sync/*; rmdir "$T/db/sync" "$T/db" "$T" 2>/dev/null; (exit $r)
